<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Record Purchase</title><style>body{font:15px Arial;background:#f4f6fa;color:#1b2940}.wrap{max-width:1100px;margin:30px auto}.card{background:white;padding:22px;border-radius:12px;margin:15px 0}input,select{padding:10px;margin:4px;border:1px solid #ccd5df;border-radius:6px;max-width:100%}button,a{background:#173d65;color:white;padding:10px 14px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}.line{display:flex;gap:6px;flex-wrap:wrap}.line select{flex:2;min-width:250px}.line input{width:130px}</style></head><body><main class="wrap"><h1>Record Purchase</h1><p><a href="{{ route('purchases.index') }}">Back</a></p>@foreach($errors->all() as $e)<p style="color:#b42318">{{ $e }}</p>@endforeach<form method="POST" action="{{ route('purchases.store') }}">@csrf<div class="card"><h2>Purchase Details</h2>@if(auth()->user()->hasRole('owner'))<select name="branch_id" required><option value="">Receiving branch</option>@foreach($branches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select>@else<input type="hidden" name="branch_id" value="{{ auth()->user()->branch_id }}"><b>{{ $branches->first()?->name }}</b>@endif<select name="supplier_id"><option value="">No supplier</option>@foreach($suppliers as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select><input name="invoice_number" placeholder="Invoice number"><input type="date" name="purchase_date" value="{{ now()->toDateString() }}" required><input type="number" min="0" step=".01" name="discount_amount" value="0" placeholder="Discount PKR"><input name="notes" placeholder="Notes"></div><div class="card"><h2>Items</h2><div id="items"><div class="line"><select name="items[0][product_variant_id]" required><option value="">Product / size / colour / SKU</option>@foreach($variants as $v)<option value="{{ $v->id }}">{{ $v->product->name }} — {{ $v->size }}/{{ $v->color }} ({{ $v->sku }})</option>@endforeach</select><input type="number" name="items[0][quantity]" min="1" value="1" required placeholder="Qty"><input type="number" name="items[0][unit_cost]" min="0" step=".01" required placeholder="Unit cost"></div></div><button type="button" onclick="addItem()">+ Add item</button> <button type="submit">Save Purchase & Receive Stock</button><p>Saving a purchase immediately increases the receiving branch stock and records each stock movement.</p></div></form></main><script>let row=1;function addItem(){let c=document.querySelector('#items .line').cloneNode(true);c.querySelectorAll('select,input').forEach(e=>{e.name=e.name.replace(/items\[0\]/,'items['+row+']');if(e.tagName==='SELECT')e.selectedIndex=0;else e.value=e.name.endsWith('[quantity]')?'1':''});document.getElementById('items').appendChild(c);row++}</script></body></html>